# Justice Center (read-only): scenario points of EVERY scenario region (any .ymt under a scenario folder) inside the box -> scenarios.tsv
param([double]$BX0 = 270, [double]$BX1 = 430, [double]$BY0 = -1720, [double]$BY1 = -1530, [string]$Dir = 'C:\Users\anton\Documents\Codex\JusticeCenter\survey')
$ErrorActionPreference = 'Stop'
$gta = 'C:\Program Files (x86)\Steam\steamapps\common\Grand Theft Auto V'
$cw = 'C:\Users\anton\Documents\Codex\2026-10-10\our-goal-is-to-build-machine\outputs\MLO-Workshop\tools\CodeWalker'
[void][Reflection.Assembly]::LoadFrom("$cw\CodeWalker.Core.dll")
[CodeWalker.GameFiles.GTA5Keys]::LoadFromPath($gta, $false, $null)
$rpf = New-Object CodeWalker.GameFiles.RpfManager
$rpf.Init($gta, $false, [Action[string]]{ param($s) }, [Action[string]]{ param($s) }, $false, $true)
$known = 'WORLD_HUMAN_SMOKING WORLD_HUMAN_STAND_IMPATIENT PROP_HUMAN_SEAT_BENCH WORLD_HUMAN_HANG_OUT_STREET WORLD_HUMAN_DRINKING WORLD_HUMAN_GUARD_STAND WORLD_HUMAN_GUARD_PATROL WORLD_VEHICLE_PARK_PERPENDICULAR_NOSE_IN WORLD_VEHICLE_PARK_PARALLEL WORLD_HUMAN_STAND_MOBILE WORLD_HUMAN_STAND_MOBILE_UPRIGHT WORLD_HUMAN_LEANING CODE_HUMAN_POLICE_INVESTIGATE WORLD_VEHICLE_POLICE_CAR WORLD_VEHICLE_POLICE_NEXT_TO_CAR WORLD_VEHICLE_POLICE_BIKE WORLD_HUMAN_COP_IDLES WORLD_HUMAN_CLIPBOARD WORLD_HUMAN_JANITOR WORLD_HUMAN_MAID_CLEAN WORLD_HUMAN_GARDENER_LEAF_BLOWER WORLD_HUMAN_GARDENER_PLANT WORLD_HUMAN_SEAT_STEPS WORLD_HUMAN_SEAT_WALL WORLD_HUMAN_SEAT_WALL_EATING WORLD_HUMAN_SEAT_WALL_TABLET WORLD_HUMAN_SEAT_LEDGE WORLD_HUMAN_SEAT_LEDGE_EATING WORLD_HUMAN_PICNIC WORLD_HUMAN_TOURIST_MAP WORLD_HUMAN_TOURIST_MOBILE WORLD_HUMAN_STAND_FIRE WORLD_HUMAN_DRUG_DEALER WORLD_HUMAN_DRUG_DEALER_HARD WORLD_VEHICLE_EMPTY WORLD_HUMAN_AA_SMOKE WORLD_HUMAN_AA_COFFEE WORLD_HUMAN_BUM_STANDING WORLD_HUMAN_BUM_SLUMPED WORLD_HUMAN_BUM_WASH WORLD_HUMAN_BUM_FREEWAY WORLD_HUMAN_HUMAN_STATUE WORLD_HUMAN_SECURITY_SHINE_TORCH WORLD_HUMAN_CAR_PARK_ATTENDANT WORLD_HUMAN_BINOCULARS WORLD_HUMAN_MUSCLE_FREE_WEIGHTS WORLD_HUMAN_MUSCLE_FLEX WORLD_HUMAN_PUSH_UPS WORLD_HUMAN_SIT_UPS WORLD_HUMAN_YOGA WORLD_HUMAN_PAPARAZZI WORLD_HUMAN_PARTYING WORLD_HUMAN_WINDOW_SHOP_BROWSE WORLD_HUMAN_WELDING WORLD_HUMAN_HAMMERING WORLD_HUMAN_CONST_DRILL WORLD_HUMAN_MOBILE_FILM_SHOCKING WORLD_HUMAN_STUPOR WORLD_HUMAN_PROSTITUTE_HIGH_CLASS WORLD_HUMAN_PROSTITUTE_LOW_CLASS WORLD_HUMAN_JOG_STANDING WORLD_HUMAN_POWER_WALKER WORLD_HUMAN_MUSICIAN WORLD_HUMAN_CHEERING WORLD_HUMAN_SUNBATHE WORLD_HUMAN_SUNBATHE_BACK WORLD_HUMAN_VEHICLE_MECHANIC WORLD_HUMAN_LEANING_CASINO_TERRACE WORLD_VEHICLE_DRIVE_SOLO WORLD_VEHICLE_DRIVE_PASSENGERS WORLD_VEHICLE_BUSINESSMEN WORLD_VEHICLE_ATTRACTOR WORLD_VEHICLE_MECHANIC WORLD_VEHICLE_SALTON WORLD_VEHICLE_STREETRACE WORLD_VEHICLE_BICYCLE_BMX WORLD_VEHICLE_BICYCLE_ROAD WORLD_VEHICLE_BICYCLE_MOUNTAIN WORLD_VEHICLE_TRUCK_LOGS WORLD_VEHICLE_TRUCKS_TRAILERS WORLD_VEHICLE_CONSTRUCTION_SOLO WORLD_VEHICLE_CONSTRUCTION_PASSENGERS WORLD_VEHICLE_FARM WORLD_VEHICLE_BOAT_IDLE WORLD_VEHICLE_AMBULANCE WORLD_VEHICLE_FIRE_TRUCK WORLD_VEHICLE_POLICE WORLD_VEHICLE_MILITARY_PLANES_SMALL WORLD_VEHICLE_PARK_PERPENDICULAR WORLD_BIRD_FEEDING? WORLD_PIGEON_FEEDING? WORLD_GULL_STANDING WORLD_GULL_FEEDING WORLD_PIGEON_STANDING? WORLD_CROW_FEEDING WORLD_DOG_SITTING_RETRIEVER WORLD_DOG_BARKING_SHEPHERD WORLD_CAT_SLEEPING_GROUND WORLD_HUMAN_WALK_DOG? Walk WALK WALK_FACILITY CODE_HUMAN_CROSS_ROAD_WAIT CODE_HUMAN_MEDIC_KNEEL CODE_HUMAN_MEDIC_TEND_TO_DEAD CODE_HUMAN_MEDIC_TIME_OF_DEATH CODE_HUMAN_POLICE_CROWD_CONTROL PROP_HUMAN_SEAT_CHAIR PROP_HUMAN_SEAT_CHAIR_UPRIGHT PROP_HUMAN_SEAT_CHAIR_FOOD PROP_HUMAN_SEAT_CHAIR_DRINK PROP_HUMAN_SEAT_ARMCHAIR PROP_HUMAN_SEAT_BAR PROP_HUMAN_SEAT_BUS_STOP_WAIT PROP_HUMAN_SEAT_COMPUTER PROP_HUMAN_SEAT_DECKCHAIR PROP_HUMAN_SEAT_MUSCLE_BENCH_PRESS PROP_HUMAN_SEAT_STRIP_WATCH PROP_HUMAN_SEAT_SUNLOUNGER PROP_HUMAN_ATM PROP_HUMAN_BBQ PROP_HUMAN_BUM_BIN PROP_HUMAN_BUM_SHOPPING_CART PROP_HUMAN_PARKING_METER PROP_HUMAN_STAND_IMPATIENT PROP_HUMAN_MUSCLE_CHIN_UPS PROP_HUMAN_MOVIE_STUDIO_LIGHT WORLD_HUMAN_STAND_GUARD WORLD_LOOKAT_POINT WORLD_HUMAN_LEANING_FOOD CODE_HUMAN_STAND_COWER WORLD_HUMAN_SEAT_STEPS_FOOD'.Split(' ') | % { $_.Trim('?') }
$hn = @{}; foreach ($n in $known) { $hn[[CodeWalker.GameFiles.JenkHash]::GenHash($n.ToLower())] = $n }
function Nm($yt, $id) { $tn = $yt.CScenarioPointRegion.LookUps.TypeNames; try { $h = [uint32]$tn[$id].Hash } catch { try { $h = [uint32]$tn[$id] } catch { return "id$id" } }; if ($hn.ContainsKey($h)) { return $hn[$h] }; return ('0x{0:X8}' -f $h) }
$rows = New-Object System.Collections.Generic.List[string]; $rows.Add("ymt`tx`ty`tz`tkind`ttype`tmodelset`tflags`ttime`tpath")
foreach ($f in $rpf.AllRpfs) { if (-not $f.AllEntries) { continue }
  foreach ($e in $f.AllEntries) { if (-not $e.Name.ToLower().EndsWith('.ymt') -or $e.Path -notmatch 'scenario') { continue }
    $yt = New-Object CodeWalker.GameFiles.YmtFile; $yt.Load($e.File.ExtractFile($e), $e)
    $sr = $yt.ScenarioRegion; if (-not $sr) { continue }
    foreach ($sn in $sr.Nodes) { $p = $sn.Position; if ($p.X -lt $BX0 -or $p.X -gt $BX1 -or $p.Y -lt $BY0 -or $p.Y -gt $BY1) { continue }
      $k = ''; $t = ''; $ms = ''; $fl = ''; $tm = ''
      if ($sn.MyPoint) { $k = 'point'; $t = Nm $yt $sn.MyPoint.TypeId; $ms = "$($sn.MyPoint.ModelSet)"; $fl = "$($sn.MyPoint.Flags)"; $tm = "$($sn.MyPoint.TimeStart)-$($sn.MyPoint.TimeEnd)" }
      elseif ($sn.ChainingNode) { $k = 'chain'; $t = "$($sn.ChainingNode.ScenarioType)" }
      elseif ($sn.EntityPoint) { $k = 'entity'; $t = "$($sn.EntityPoint.Type)" }
      elseif ($sn.ClusterMyPoint) { $k = 'cluster'; $t = "$($sn.ClusterMyPoint.Type)" }
      $rows.Add("$($e.Name)`t$([math]::Round($p.X,2))`t$([math]::Round($p.Y,2))`t$([math]::Round($p.Z,2))`t$k`t$t`t$ms`t$fl`t$tm`t$($e.Path)") } } }
[IO.File]::WriteAllLines("$Dir\scenarios.tsv", $rows); "rows $($rows.Count - 1)"
